class KthLargest {
private:
    int k_;
    priority_queue<int, vector<int>, greater<int>> minHeap_;
public:
    KthLargest(int k, vector<int>& nums) : k_(k) {
        for (int x : nums) {
            minHeap_.push(x);
            if (static_cast<int>(minHeap_.size()) > k_) {
                minHeap_.pop();
            }
        }
    }

    int add(int val) {
        minHeap_.push(val);
        if (static_cast<int>(minHeap_.size()) > k_) {
            minHeap_.pop();
        }
        return minHeap_.top();
    }
};
